---礼包点击处理
---@param type integer 礼包类型
function StoreLevelGift:GiftOnClickHandler(type)
    local data = nil
    local lastGiftId = nil
    local str = localize("已领取完全部的基础补给")
    if type == GiftType.FREE then
        data = self._levelGiftData.levelGiftsFree
        lastGiftId = checkInt(data.levelGiftsFreeLast)
    elseif type == GiftType.PAY then
        data = self._levelGiftData.levelGiftsPay
        lastGiftId = checkInt(data.levelGiftsPayLast)
        str = localize("已领取完全部的突破补给")
    end

    local giftList = checkTable(data.giftList)
    local curGiftData = self:GetGiftByLastGiftId(giftList, lastGiftId)
    local hasNextGift = curGiftData and true or false

    if not hasNextGift then
        GameUtils.Toast(str)
        return
    end

    if not hasNextGift then
        -- 没有下一级礼包的时候显示最后领取的礼包
        curGiftData = self:GetGiftByGiftId(giftList, lastGiftId)
    end
    
    -- 礼包点击埋点
    xRecord.record("4-010", string.format("click_lvl_pack_%d", checkInt(curGiftData.id)))
    
    local prices = {}
    if type == GiftType.FREE then
        if StoreUtils.CheckPlayerLevelSatisfy(curGiftData.level) and hasNextGift then
            -- 免费礼包无需显示通用购买弹窗
            self:RequestMallBuyLevelGift(curGiftData.id, type)
            return 
        end
        prices = {
            {
                current = 0,
                currency = Constants.Currency.FreeDiamondId,
            }
        }
    elseif type == GiftType.PAY then
        for _, v in ipairs(checkTable(curGiftData.consume)) do
            local price = {
                current = v.num,
                currency = v.goodsId,
            }
            table.insert(prices, price)
        end
    end

    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = {
        goodsId        = curGiftData.showId,
        goodsNum       = -1,
        prices         = prices,
        rewards        = curGiftData.rewards,
        levelLimit     = curGiftData.level,
        maxBuyNum      = hasNextGift and 1 or 0,
        endTime        = -1,
        
        buyCb          = function (price, buyNum)
            self:BuyButtonOnclickHandler(curGiftData, type)
        end
    }})
end

---通用购买页面购买点击回调
function StoreLevelGift:BuyButtonOnclickHandler(curGiftData, type)
    if not StoreUtils.CheckPlayerLevelSatisfy(curGiftData.level) then
        -- 调查官等级不足
        return
    end

    if type == GiftType.PAY then
        -- 判断道具是否充足
        if not StoreUtils.CheckConsume(curGiftData.consume) then return end
        
        self:RequestMallBuyLevelGift(curGiftData.id, type)
    else
        -- 购买请求
        self:RequestMallBuyLevelGift(curGiftData.id, type)
    end
end

-- 礼包购买 response处理
function StoreLevelGift:BuyLevelGiftResponseHandler(request, response)
    if checkNumber(response.errCode) == 0 then
        local responseData = checkTable(response.data)
        if #responseData.rewards > 0 then
            if self._BuyType == GiftType.PAY then
                -- 扣除消耗
                local data = self._levelGiftData.levelGiftsPay
                local lastGiftId = checkInt(data.levelGiftsPayLast)
                local giftList = checkTable(data.giftList)
                local curGiftData = self:GetGiftByLastGiftId(giftList, lastGiftId)
                local consume = clone(curGiftData.consume)
                for _, v in ipairs(consume) do
                    v.num = -v.num
                end
                GoodsUtils.DrawRewards(consume)
                
                -- 更新本地数据
                self._levelGiftData.levelGiftsPay.levelGiftsPayLast = self._BuyGiftId
            elseif self._BuyType == GiftType.FREE then
                -- 更新本地数据
                self._levelGiftData.levelGiftsFree.levelGiftsFreeLast = self._BuyGiftId
                self:UpdateRedPoint()
            end
            GoodsUtils.DrawRewards(responseData.rewards)

            CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { 
                rewards = responseData.rewards,
                cb      = function()
                    blocker:AddCondition(BlockerName)
                    self:PlayReceiveAnimation(self._BuyType)
                end
            } })
        end
    end
end
--endregion handler

--region public
---刷新自身
function StoreLevelGift:Refresh(data)
    self.data = data
    xRecord.record('4-009')
    GameUtils.Request(Interfaces.OverseaWelfareLevelGift,{},function(request,response)
        if checkInt(response.errCode) == 0  then
            local responseData = response.data
            local levelGiftData = responseData.levelGift
            -- 付费礼包
            local payData = {}
            for _, data in ipairs(levelGiftData.levelGiftsPay.giftList) do
                local dojo = StoreLevelGiftDojo.New()
                dojo:Fill(data)
                table.insert(payData, dojo)
            end
            levelGiftData.levelGiftsPay.giftList = payData
            -- 免费礼包
            local freeData = {}
            for _, data in ipairs(levelGiftData.levelGiftsFree.giftList) do
                local dojo = StoreLevelGiftDojo.New()
                dojo:Fill(data)
                table.insert(freeData, dojo)
            end
            levelGiftData.levelGiftsFree.giftList = freeData
            self._levelGiftData = levelGiftData
            self:RefreshGift()
        end
    end)
end
--endregion public

--region private
---刷新礼包
function StoreLevelGift:RefreshGift()
    for _, v in pairs(GiftType) do
        self:RefreshGiftNode(v)
    end
end

---刷新礼包节点
---@param type integer 礼包类型
function StoreLevelGift:RefreshGiftNode(type)
    local data = nil
    local lastGiftId = nil
    local parentNode = nil
    if type == GiftType.FREE then
        data = self._levelGiftData.levelGiftsFree
        lastGiftId = checkInt(data.levelGiftsFreeLast)
        parentNode = self.BaseGroup
    elseif type == GiftType.PAY then
        data = self._levelGiftData.levelGiftsPay
        lastGiftId = checkInt(data.levelGiftsPayLast)
        parentNode = self.AdvancedGroup
    else
        return 
    end
    
    local giftList = checkTable(data.giftList)
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local level = checkInt(playerComponent.playerDojo.level)
    
    local curGiftData = self:GetGiftByLastGiftId(giftList, lastGiftId)
    local hasNextGift = curGiftData and true or false
    if not hasNextGift then
        -- 没有下一级礼包的时候显示最后领取的礼包
        curGiftData = self:GetGiftByGiftId(giftList, lastGiftId)
    end
    local isLock = level < checkInt(curGiftData.level)
    
    
    -- 礼包图标
    self:RefreshGiftIcon(parentNode, curGiftData.showId)
    
    -- 礼包等级
    self:RefreshGiftLevel(parentNode, curGiftData.level, isLock)
    
    -- 奖励列表
    local rewardsNode = parentNode:Find("Rewards")
    local rewards = checkTable(curGiftData.rewards)
    self:RefreshRewardsList(rewardsNode, rewards)
    
    -- 领取按钮状态
    self:RefreshBtn(parentNode, hasNextGift, isLock, curGiftData.consume)
end

---刷新礼包icon
---@param parentGO UnityEngine.GameObject 父节点
---@param goodsId  integer                道具id
function StoreLevelGift:RefreshGiftIcon(parentGO, goodsId)
    local giftGoodsPhotoPath = GoodsConfMgr:GetInstance():GetPhotoPathById(checkInt(goodsId))
    local giftIcon = parentGO:Find("ImgGiftIcon")
    CfUtils.FillImage(giftIcon, giftGoodsPhotoPath)
end

---刷新礼包等级
---@param parentGO UnityEngine.GameObject 父节点
---@param level    integer                礼包等级
---@param isLock   boolean                是否锁定
function StoreLevelGift:RefreshGiftLevel(parentGO, level, isLock)
    local textNum = parentGO:Find("TitleGroup/TxtNumber")
    CfUtils.FillText(textNum, level)
    local tips = parentGO:Find("TxtLockTips")
    if isLock then
        KTool.SetActive(tips, true)
        CfUtils.FillText(tips, localize("需调查官达到<color=#ff1d87>_num_</color>级解锁", {_num_ = level}))
    else
        KTool.SetActive(tips, false)
    end
end

---刷新奖励列表
---@param parentGO UnityEngine.GameObject 父节点
---@param rewards  table                  奖励数据
function StoreLevelGift:RefreshRewardsList(parentGO, rewards)
    local viewNode = parentGO:Find("View")
    local goodsNode = parentGO:Find("GoodNode")
    KTool.DestroyGameObjectChildren(viewNode.gameObject)
    for i, v in ipairs(rewards) do
        local go = CfUtils.InstantiateGo(goodsNode, viewNode.gameObject)
        KTool.SetActive(go, true)
        local env = CfUtils.GetLuaScr(go.transform:Find("GoodNode"), GoodsNodePath)
        env:Reload(
                {
                    goodsId = v.goodsId,
                    text = "x" .. v.num,
                    isShowNo = true
                }
        )
        env:SetClickButtonAction(function(goodsId)
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            if isTable(goodsVo) then
                GameUtils.ShowCommonTipsBoard(go.gameObject, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
            end
        end)
    end
    -- 超过3个要设置列表初始位置
    if #rewards > 3 then
        viewNode.transform.pivot = Vector2.New(0, 0.5)
        viewNode.transform.anchoredPosition = Vector3(0, 0, 0)
    else
        viewNode.transform.pivot = Vector2.New(0.5, 0.5)
    end
end

---刷新按钮
---@param parentGO    UnityEngine.GameObject 父节点GO
---@param hasNextGift boolean                是否拥新的礼包
---@param isLock      boolean                是否锁定
---@param consume     table                  消耗
function StoreLevelGift:RefreshBtn(parentGO, hasNextGift, isLock, consume)
    if isNull(parentGO) then return end
    
    local btnGO = parentGO:Find("BtnGroup")
    -- 可领取时的特效
    local btnEffect = parentGO:Find('UIFX_StoreLevelGiftEffectCanTake')

    if not hasNextGift then
        -- 没有新的礼包
        self:SwitchBtnState(btnGO, BtnState.SOLD_OUT, consume)
        KTool.SetActive(btnEffect, false)
        return
    end

    if isLock then
        -- 礼包锁定
        self:SwitchBtnState(btnGO, BtnState.LOCK, consume)
        KTool.SetActive(btnEffect, false)
        return
    end
    
    -- 可以使用
    self:SwitchBtnState(btnGO, BtnState.GET, consume)
    KTool.SetActive(btnEffect, true)
end

---切换按钮状态
---@param btnGO   UnityEngine.GameObject 按钮GO
---@param state   integer                状态
---@param consume table                  消耗
function StoreLevelGift:SwitchBtnState(btnGO, state, consume)
    local isFree = next(consume) == nil
    if isFree then
        self:SwitchFreeBtnState(btnGO, state)
    else
        self:SwitchPayBtnState(btnGO, state, consume)
    end
end

---切换免费礼包按钮状态
---@param btnGO UnityEngine.GameObject 按钮GO
---@param state integer                状态
function StoreLevelGift:SwitchFreeBtnState(btnGO, state)
    local btnBg = btnGO:Find("BtnBg")
    local imgCode = btnGO:Find("ImgCode")
    local txtBtn = btnGO:Find("TxtBtn")
    CfUtils.SetUISwitchImage(btnBg, state)
    CfUtils.SetUISwitchImage(imgCode, state)
    CfUtils.SetUISwitchText(txtBtn, state)
end

---切换付费礼包按钮状态
---@param btnGO   UnityEngine.GameObject 按钮GO
---@param state   integer                状态
---@param consume table                  消耗
function StoreLevelGift:SwitchPayBtnState(btnGO, state, consume)
    local priceGroup = btnGO:Find("PriceGroup")
    local txtSoldOutBtn = btnGO:Find("TxtSoldOutBtn")
    if state == BtnState.GET then
        KTool.SetActive(priceGroup, true)
        KTool.SetActive(txtSoldOutBtn, false)
        self:RefreshGiftPayPrice(priceGroup, state, consume)
    elseif state == BtnState.LOCK then
        KTool.SetActive(priceGroup, true)
        KTool.SetActive(txtSoldOutBtn, false)
        self:RefreshGiftPayPrice(priceGroup, state, consume)
    elseif state == BtnState.SOLD_OUT then
        KTool.SetActive(priceGroup, false)
        KTool.SetActive(txtSoldOutBtn, true)
    end
end

---刷新付费礼包价格
---@param priceGO UnityEngine.GameObject 价格GO
---@param state   integer                状态
---@param consume table                  消耗
function StoreLevelGift:RefreshGiftPayPrice(priceGO, state, consume)
    local icon = priceGO:Find('CurPrice/Icon')
    local price = priceGO:Find("CurPrice/Txtprice")
    local goodsVo = GoodsConfMgr:GetGoodsVoById(consume[1].goodsId)
    CfUtils.FillImage(icon, goodsVo.photoPath)
    CfUtils.FillText(price, consume[1].num)
    if state == BtnState.GET then
        CfUtils.SetColor(price, XLuaUtils.HexToColor("#FFFFFF"))
    elseif state == BtnState.LOCK then
        CfUtils.SetColor(price, XLuaUtils.HexToColor("#8C8C8C"))
    end
end

---通过最新的礼包id获取当前显示的礼包数据
---@param giftList StoreLevelGiftDojo[] 礼包列表
---@param lastGiftId integer 最后领取的id
---@return StoreLevelGiftDojo 无后续礼包时返回false
function StoreLevelGift:GetGiftByLastGiftId(giftList, lastGiftId)
    for i, v in ipairs(checkTable(giftList)) do
        if checkInt(v.lastGiftId) == checkInt(lastGiftId) then
            return v
        end
    end
    return false
end

---通过礼包id获取礼包数据
---@param giftList StoreLevelGiftDojo[] 礼包列表
---@param giftId integer 最后领取的id
---@return StoreLevelGiftDojo 礼包数据 
function StoreLevelGift:GetGiftByGiftId(giftList, giftId)
    for i, v in ipairs(checkTable(giftList)) do
        if checkInt(v.id) == checkInt(giftId) then
            return v
        end
    end
end

---播放领奖动画
---@param type integer 礼包类型
function StoreLevelGift:PlayReceiveAnimation(type)
    local anim = nil
    local effect = nil
    if type == GiftType.FREE then
        anim = self.BaseGroup:GetComponent(typeof(Animation))
        effect = self.BaseGroup:Find("UIFX_StoreLevelGiftEffectRefresh")
    elseif type == GiftType.PAY then
        anim = self.AdvancedGroup:GetComponent(typeof(Animation))
        effect = self.AdvancedGroup:Find("UIFX_StoreLevelGiftEffectRefresh")
    else
        self:RefreshGift()
    end
    self.co = cs_coroutine.start(function ()
        KTool.SetActive(effect, true)
        anim:Play()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(anim.clip.length))
        self._BuyType = nil
        self._BuyGiftId = nil
        KTool.SetActive(effect, false)
        self:RefreshGift()
        blocker:RemoveCondition(BlockerName)
    end)
end

---停止协程
function StoreLevelGift:StopCo()
    if self.co then
        cs_coroutine.stop(self.co)
        self.co = nil
    end
end

---礼包购买请求
---@param giftId integer 礼包id
---@param type   integer 礼包类型
function StoreLevelGift:RequestMallBuyLevelGift(giftId, type)
    GameUtils.Request(Interfaces.MallBuyLevelGift, {giftId = giftId, type = type}, Bind(self, self.BuyLevelGiftResponseHandler))
    self._BuyType = type
    self._BuyGiftId = giftId
end

---更新红点
function StoreLevelGift:UpdateRedPoint()
    -- 只有免费礼包可领取时才会有红点
    local giftsFreeData = self._levelGiftData.levelGiftsFree
    local curGiftData = self:GetGiftByLastGiftId(giftsFreeData.giftList, giftsFreeData.levelGiftsFreeLast)
    local visible = curGiftData and StoreUtils.CheckPlayerLevelSatisfy(curGiftData.level) or false
    GameUtils.UpdateServerRedPointData({unFreeLevelChest = visible and 0 or -1})
end
--endregion private

return StoreLevelGift